  "You decide what Petto keeps. Anyone can look up a history by ID, but only you can delete yours.": "Você decide o que o Petto guarda. Qualquer pessoa pode buscar um histórico por ID, mas só você pode apagar o seu.",
  "Your history is saved again.": "Seu histórico é salvo de novo.",
  "Your privacy": "Sua privacidade",
  "History": "Histórico",
  "A saved design from the Embeds page. It can use {monkey.count}, {monkey.link}, {monkey.content}, {monkey.image} and the other monkey variables.": "Um design salvo da página Embeds. Pode usar {monkey.count}, {monkey.link}, {monkey.content}, {monkey.image} e as outras variáveis monkey.",
  "Monkeyboard": "Monkeyboard",
  "Save monkeyboard": "Salvar monkeyboard",
  "The starboard's opposite: messages that get enough monkeys are collected in their own channel.": "O oposto do starboard: as mensagens que recebem macacos suficientes são reunidas no seu próprio canal.",
  "A design from Embeds is sent instead of the message. Its variables work, but not {age}.": "Um design de Embeds é enviado no lugar da mensagem. As variáveis funcionam, mas {age} não.",
  "An invite shown as a Join button on the page. Optional.": "Um convite mostrado como botão de entrar na página. Opcional.",
  "Anyone with the link can see the ranking of this server on the website: names, pictures, levels and XP.": "Qualquer pessoa com o link pode ver o ranking deste servidor no site: nomes, fotos, níveis e XP.",
  "Birthdays saved": "Aniversários salvos",
