  "Time zone": "Fuso horário",
  "Variables: {user}, {user.mention}, {server} and {age} (the age they turn, empty if they did not say the year).": "Variáveis: {user}, {user.mention}, {server} e {age} (a idade que fazem, vazia se não disseram o ano).",
  "Birthday messages": "Mensagens de aniversário",
  "The messages that celebrate a member's birthday.": "As mensagens que comemoram o aniversário de um membro.",
  "Unsaved changes. Press Save to apply them all.": "Há alterações não salvas. Clique em Salvar para aplicá-las todas.",
  "Save multipliers": "Salvar multiplicadores",
  "Save rewards": "Salvar recompensas",
  "{a} h": "{a} h",
  "Delete this autoresponder": "Excluir esta resposta automática",
  "Trigger word": "Palavra de gatilho",
  "The title/color/footer only apply when set to embed, the reply text above becomes the embed description. Use <code>{a}</code> in that field to react to the sent embed.": "O título, a cor e o rodapé só valem quando enviado como embed; o texto de resposta acima vira a descrição do embed. Use <code>{a}</code> nesse campo para reagir ao embed enviado.",
  "Picking a saved template here uses its visual design. The reply field still accepts flags such as <code>{a}</code>; templates are managed on the Embeds page.": "Escolher aqui um modelo salvo usa o design visual dele. O campo de resposta ainda aceita flags como <code>{a}</code>; os modelos são gerenciados na página de Embeds.",
  "Sticky messages <span class=\"am-count\">{a}</span>": "Mensagens fixas <span class=\"am-count\">{a}</span>",
  "Message to keep pinned to the bottom": "Mensagem mantida no fim do canal",
  "One sticky per channel, adding another in the same channel replaces it. After you save, the bot deletes and re-sends it every time someone posts in that channel, so it always stays at the bottom. Use <code>{a}</code> for a line break, <code>{b}</code> for a divider line. Choose a saved embed (a V2 design too) to send it instead of the text; the text is used if the embed is missing.": "Uma mensagem fixa por canal; adicionar outra no mesmo canal substitui a anterior. Depois de salvar, o bot a apaga e a reenvia sempre que alguém escreve nesse canal, assim ela fica sempre no fim. Use <code>{a}</code> para uma quebra de linha e <code>{b}</code> para uma linha divisória. Escolha um embed salvo (também um design V2) para enviá-lo no lugar do texto; se o embed faltar, o texto é usado.",
  "Reaction roles <span class=\"am-count\">{a}</span>": "Cargos por reação <span class=\"am-count\">{a}</span>",
  "Message ID": "ID da mensagem",
  "Emoji or custom emoji": "Emoji ou emoji personalizado",
  "Role": "Cargo",
  "add only": "somente adicionar",
  "remove only": "somente remover",
  "Button label (optional)": "Texto do botão (opcional)",
  "Use reaction mode for emoji reactions or button mode for a clickable role menu. Button mode can add up to 25 buttons to a message without another component panel.": "Use o modo reação para reações com emoji ou o modo botão para um menu de cargos clicável. O modo botão pode adicionar até 25 botões a uma mensagem sem outro painel de componentes.",
  "Auto-threading <span class=\"am-count\">{a}</span>": "Tópicos automáticos <span class=\"am-count\">{a}</span>",
  "Thread name": "Nome do tópico",
