  "No template, use message text above": "Sem modelo, usar o texto acima",
  "Starts a thread off every new message in the channel, good for support/showcase channels where each message deserves its own conversation.": "Cria um tópico a partir de cada nova mensagem do canal, ideal para canais de suporte ou de exibição em que cada mensagem merece sua própria conversa.",
