  "Keep your server configuration safe, export a snapshot whenever you need it, and let Petto create copies on a schedule. Backup numbers are scoped to this server.": "Mantenha a configuração do seu servidor segura, exporte um instantâneo quando precisar e deixe o Petto criar cópias de forma agendada. Os números dos backups são próprios deste servidor.",
