  "Shared by every server Petto is in, can't be edited from a single server. What you set on the left only changes how Petto looks here.": "Compartilhada por todos os servidores em que o Petto está, não pode ser editada em um só servidor. O que você definir à esquerda só muda como o Petto aparece aqui.",
