  "Max 190 characters. Custom emoji like": "Máximo de 190 caracteres. Emojis personalizados como",
  "render fine.": "aparecem normalmente.",
  "Embeds": "Embeds",
  "Rich message templates for <b>{a}</b>. Point a custom command or autoresponder at one by name, or send it directly with <code>/embed send</code>.": "Modelos de mensagens ricas para <b>{a}</b>. Aponte um comando personalizado ou uma resposta automática para um deles pelo nome, ou envie direto com <code>/embed send</code>.",
  "The base settings every other system in <b>{a}</b> builds on.": "As configurações base sobre as quais os demais sistemas de <b>{a}</b> são construídos.",
  "Saved. Petto picks this up right away, no restart needed.": "Salvo. O Petto aplica na hora, sem reiniciar.",
  "Reset. Prefix, mute role, and the bot's look in this server are back to default.": "Redefinido. O prefixo, o cargo de silêncio e a aparência do bot neste servidor voltaram ao padrão.",
  "Basic settings": "Configurações básicas",
  "The base every other system in this server reads from.": "A base da qual todos os outros sistemas deste servidor leem.",
  "Server language": "Idioma do servidor",
  "The language Petto uses in this server: its messages, buttons and the private messages it sends. It applies right away. Members can also use <code>{a}language</code>. Help us translate: <a href=\"/apply?role=translator\">apply as a translator</a>.": "O idioma que o Petto usa neste servidor: suas mensagens, botões e as mensagens privadas que envia. Vale na hora. Também dá para usar <code>{a}language</code>. Ajude a traduzir: <a href=\"/apply?role=translator\">candidate-se como tradutor</a>.",
  "The language of Petto's messages in this server. Members can also use <code>{a}language</code>. Help us translate: <a href=\"/apply?role=translator\">apply as a translator</a>.": "O idioma das mensagens do Petto neste servidor. Também dá para usar <code>{a}language</code>. Ajude a traduzir: <a href=\"/apply?role=translator\">candidate-se como tradutor</a>.",
