  "Write a prefix first.": "Escreva um prefixo primeiro.",
  "A prefix has at most {n} characters.": "Um prefixo tem no máximo {n} caracteres.",
  "A prefix cannot have spaces.": "Um prefixo não pode ter espaços.",
