  "Jump to a part of the file": "Ir para uma parte do arquivo",
  "Read-only, a snapshot of what's saved. Change it from its own page of the dashboard, not by editing this.": "Somente leitura, um instantâneo do que está salvo. Altere pela própria página do painel, não editando isto.",
  "Download": "Baixar",
  "A JSON file with the settings of these modules, row by row. Keep it as a copy or to compare two servers. Petto cannot import it back.": "Um arquivo JSON com as configurações desses módulos, linha por linha. Guarde como cópia ou para comparar dois servidores. O Petto não consegue importá-lo de volta.",
  "To bring back the server itself (roles, channels, emojis), use": "Para recuperar o servidor em si (cargos, canais, emojis), use",
  "What is in a snapshot": "O que há em uma captura",
  "Included": "Incluído",
  "The prefix, the mute role and the bot's look (nickname, picture, banner, about me).": "O prefixo, o cargo de silêncio e a aparência do bot (apelido, imagem, banner, sobre mim).",
  "The settings of AutoMod, anti-nuke, levels, giveaways, reports, booster roles, welcome, leave and boost messages, verification, bump reminders and ping on join.": "As configurações de AutoMod, anti-nuke, níveis, sorteios, denúncias, cargos de booster, mensagens de boas-vindas, saída e boost, verificação, lembretes de bump e ping ao entrar.",
  "How many custom commands, autoresponders, sticky messages, reaction roles, timers, feeds, counters, log channels, ticket categories, level rewards, saved embeds and image cards the server has. The JSON file has each one, row by row.": "Quantos comandos personalizados, respostas automáticas, mensagens fixas, cargos por reação, temporizadores, feeds, contadores, canais de log, categorias de tickets, recompensas de nível, embeds salvos e cartões de imagem o servidor tem. O arquivo JSON traz cada um, linha por linha.",
  "Not included": "Não incluído",
  "Members' data: XP and levels, warnings, cases, notes and tickets.": "Dados dos membros: XP e níveis, avisos, casos, notas e tickets.",
  "Messages, and the pictures and files you uploaded.": "Mensagens, e as imagens e arquivos que você enviou.",
  "Tokens, keys and passwords.": "Tokens, chaves e senhas.",
  "Premium, billing and dashboard access.": "Premium, cobrança e acesso ao painel.",
  "The settings of pages not listed above, such as suggestions, forms, birthdays and permissions.": "As configurações de páginas que não aparecem acima, como sugestões, formulários, aniversários e permissões.",
  "Danger zone": "Zona de perigo",
  "Reset config puts these back to their defaults:": "Redefinir configuração devolve isto aos valores padrão:",
  "The command prefix goes back to !.": "O prefixo de comandos volta para !.",
  "The mute role is cleared, so Petto uses Discord's native timeout.": "O cargo de silêncio é removido, então o Petto usa o timeout nativo do Discord.",
  "The bot's nickname, picture, banner and about me in this server (on Discord too).": "O apelido, a imagem, o banner e o sobre mim do bot neste servidor (no Discord também).",
  "Nothing else changes: AutoMod, levels, automation and the other modules, and the members' data, stay as they are. This can't be undone.": "Nada mais muda: AutoMod, níveis, automação e os outros módulos, nem os dados dos membros. Não dá para desfazer.",
  "Entry style, messages, and bonus-entry presets for giveaways in <b>{a}</b>. Start one with <code>/giveaway start</code>.": "Estilo de entrada, mensagens e predefinições de entradas extras para sorteios em <b>{a}</b>. Inicie um com <code>/giveaway start</code>.",
