  "Mentions new members in these channels, then cleans the ping up after the delay below (default 5s).": "Menciona os novos membros nestes canais e depois apaga a menção após o atraso abaixo (5 s por padrão).",
  "Delay": "Atraso",
  "Seconds before the ping message is deleted": "Segundos antes de apagar a mensagem da menção",
  "Permissions": "Permissões",
  "A custom 0-100 authorization level, layered on top of Discord's own permissions, for every command in <b>{a}</b>. Click any ring segment to edit it, bars reach further out the higher the required level. The server owner and anyone with Administrator always bypass this.": "Um nível de autorização personalizado de 0 a 100, sobre as permissões do próprio Discord, para cada comando em <b>{a}</b>. Clique em qualquer segmento do anel para editá-lo; as barras vão mais longe quanto maior o nível exigido. O dono do servidor e qualquer pessoa com Administrador sempre ignoram isso.",
  "Prefix-only access": "Acesso somente com prefixo",
  "These same groups and command levels also work from Discord. The server prefix is configurable;": "Estes mesmos grupos e níveis de comandos também funcionam pelo Discord. O prefixo do servidor é configurável;",
  "is only the default.": "é apenas o padrão.",
  "Premium · Petto": "Premium · Petto",
  "Premium workspace": "Espaço de trabalho Premium",
