  "Discord did not respond. Refresh in a few seconds.": "O Discord não respondeu. Atualize em alguns segundos.",
  "We could not save that server preference. Try again.": "Não conseguimos salvar essa preferência de servidor. Tente de novo.",
  "You can only select servers where you have Manage Server or Administrator.": "Você só pode escolher servidores em que tenha Gerenciar servidor ou Administrador.",
  "Checkout is not connected yet. Add the Polar access token to the dashboard environment first.": "O pagamento ainda não está conectado. Adicione primeiro o token de acesso da Polar ao ambiente do dashboard.",
  "We could not open the billing portal. Your subscription is still safe; try again in a moment.": "Não conseguimos abrir o portal de cobrança. Sua assinatura continua segura; tente de novo em instantes.",
  "This server does not have an active Premium slot yet. Choose it below after Premium is activated.": "Este servidor ainda não tem um espaço Premium ativo. Escolha-o abaixo depois de ativar o Premium.",
  "Server preference saved.": "Preferência de servidor salva.",
  "Checkout returned successfully. Polar is confirming your subscription; this page will update as soon as the webhook arrives.": "O pagamento foi concluído. A Polar está confirmando sua assinatura; esta página será atualizada assim que o webhook chegar.",
  "Premium stays optional. The plans appear now; checkout activates after the Polar access token is added to the dashboard environment.": "O Premium continua opcional. Os planos aparecem agora; o pagamento é ativado depois de adicionar o token de acesso da Polar ao ambiente do dashboard.",
