  "How /levels rank answers. The card is a picture with the avatar, the name, the level and a progress bar; the embed is the text version. Make or edit cards in Image cards.": "Como o /levels rank responde. O cartão é uma imagem com o avatar, o nome, o nível e uma barra de progresso; o embed é a versão em texto. Crie ou edite cartões em Cartões de imagem.",
