  "No voice XP while muted": "Sem XP de voz enquanto silenciado",
  "Voice XP is earned also when you are alone. Deafened members and the server's AFK channel never earn it.": "O XP de voz também é ganho estando sozinho. Quem está ensurdecido e o canal de AFK do servidor nunca o ganham.",
  "Voice XP needs at least {a} people in the channel. Deafened members and the server's AFK channel never earn it.": "O XP de voz precisa de pelo menos {a} pessoas no canal. Quem está ensurdecido e o canal de AFK do servidor nunca o ganham.",
  "Muted members do not earn it either.": "Quem está silenciado também não o ganha.",
  "Change it in Rules and events": "Mude em Regras e eventos",
  "1 also earns voice XP when you are alone. Bots and deafened members do not count as company.": "Com 1 também se ganha XP de voz estando sozinho. Bots e quem está ensurdecido não contam como companhia.",
  "Relaxed": "Relaxado",
  "Everything counts, even short messages and repeats. Voice earns alone, at full XP.": "Tudo conta, até mensagens curtas e repetidas. A voz ganha estando sozinho, com todo o XP.",
  "Short messages and repeats earn nothing. Voice earns alone, at half XP.": "Mensagens curtas e repetidas não ganham nada. A voz ganha estando sozinho, com metade do XP.",
  "Longer messages, a daily limit, and voice only with company and the microphone on.": "Mensagens mais longas, um limite diário, e voz só com companhia e o microfone ligado.",
  "Messages shorter than {a} characters earn nothing.": "Mensagens com menos de {a} caracteres não ganham nada.",
  "Every message counts, however short.": "Toda mensagem conta, por curta que seja.",
  "The same text again within a minute earns nothing.": "O mesmo texto de novo em um minuto não ganha nada.",
  "At most {a} XP a day from messages.": "No máximo {a} XP por dia com mensagens.",
  "No daily limit.": "Sem limite diário.",
  "Start from a profile": "Começar de um perfil",
  "A profile fills the Chat and Voice rules in one go. Nothing is saved until you press Save, and you can change any field after.": "Um perfil preenche as regras de Chat e Voz de uma vez. Nada é salvo até você apertar Salvar, e depois você pode mudar qualquer campo.",
  "Chat": "Chat",
  "Daily XP limit from messages": "Limite de XP por dia com mensagens",
  "The most XP a member can earn from messages in a day. 0 means no limit. The daily bonus is not counted.": "O máximo de XP que um membro pode ganhar com mensagens em um dia. 0 é sem limite. O bônus diário não conta.",
  "XP while alone (%)": "XP estando sozinho (%)",
  "Only matters when 1 person is enough. 100 is all the XP, 50 is half, 0 gives nothing while alone.": "Só importa quando 1 pessoa basta. 100 é todo o XP, 50 é metade, 0 não dá nada estando sozinho.",
  "Only with the microphone on (no voice XP while muted)": "Só com o microfone ligado (sem XP de voz estando silenciado)",
