  "Ping the role inside the thread (its members are added to it)": "Mencionar o cargo dentro do tópico (os membros dele são adicionados)",
  "Hide an idle thread after": "Ocultar um tópico inativo depois de",
  "1 hour": "1 hora",
  "1 day": "1 dia",
  "3 days": "3 dias",
  "1 week": "1 semana",
  "Petto needs the Create Public Threads permission in the alert channel.": "O Petto precisa da permissão Criar tópicos públicos no canal de alertas.",
  "How to complete it (the method)": "Como completá-la (o método)",
  "A message that tells how to complete the quests, written once and sent with each new quest. It can have several texts, pictures and buttons if you make it as a saved embed.": "Uma mensagem que explica como completar as missões, escrita uma vez e enviada com cada missão nova. Pode ter vários textos, imagens e botões se você fizer como embed salvo.",
  "Send the method with each new quest": "Enviar o método com cada missão nova",
  "Or a plain text": "Ou um texto simples",
  "Step 1: ...": "Passo 1: ...",
  "Used when there is no saved embed, or when it is missing. The quest variables work, such as {quest.name} and {quest.task}.": "Usado quando não há embed salvo ou quando ele falta. As variáveis da missão funcionam, como {quest.name} e {quest.task}.",
  "Where it goes": "Para onde vai",
  "In the thread of the alert": "No tópico do alerta",
  "In a channel": "Em um canal",
  "Channel for the method": "Canal para o método",
  "The alert channel": "O canal de alertas",
  "Ping the role with the method": "Mencionar o cargo com o método",
  "Send the method now": "Enviar o método agora",
  "Sends it for the newest active quest, in its thread or in the channel above. Save your changes first.": "Envia para a missão ativa mais recente, no tópico dela ou no canal acima. Salve suas alterações primeiro.",
  "A different design for each reward": "Um design diferente para cada recompensa",
  "Choose a saved embed (normal or V2) for the kinds of reward you want to look different, such as Orbs or avatar decorations. A quest uses the one of its reward; if there is none, the general design above.": "Escolha um embed salvo (normal ou V2) para os tipos de recompensa que você quer diferentes, como Orbs ou decorações de avatar. Uma missão usa o da sua recompensa; se não houver, o design geral de cima.",
  "The general design": "O design geral",
  "The general method": "O método geral",
