  "Give some of the messages Petto sends their own name and picture. They go out through a webhook that Petto makes in the channel (it needs Manage Webhooks); if it cannot, the message is sent the normal way.": "Dê a algumas mensagens que o Petto envia seu próprio nome e imagem. Elas saem por um webhook que o Petto cria no canal (precisa de Gerenciar webhooks); se não puder, a mensagem é enviada do jeito normal.",
