  "Counts the partnerships of <b>{a}</b>: a Partner Manager posts the invite of another server in a partner channel and, if it passes the requirements, it is counted.": "Conta as parcerias de <b>{a}</b>: um Partner Manager publica o convite de outro servidor em um canal de parceiros e, se cumprir os requisitos, é contado.",
  "Only the first {a} channels were kept. Premium raises the limit.": "Só os primeiros {a} canais foram mantidos. O Premium aumenta o limite.",
