  "In a menu, choosing one takes back the roles the others give": "Em um menu, escolher um tira os cargos que os outros dão",
  "Sending a claimed request back to open by itself is a Premium feature.": "Devolver sozinho um pedido reivindicado para aberto é um recurso Premium.",
  "Counts the messages with files in the channels you choose, for <b>{a}</b>. The first upload of a member gives the uploader role and sends a welcome.": "Conta as mensagens com arquivos nos canais que você escolher, em <b>{a}</b>. O primeiro upload de um membro dá o cargo de uploader e envia boas-vindas.",
  "Count uploads": "Contar uploads",
  "Upload channels": "Canais de uploads",
  "Hold Ctrl or Command to choose several. Free servers can have {a}, Premium 100.": "Segure Ctrl ou Command para escolher vários. Um servidor Free pode ter {a}, Premium 100.",
  "Uploader role": "Cargo de uploader",
  "Welcome at the first upload": "Boas-vindas no primeiro upload",
  "Nobody has uploaded in this period.": "Ninguém fez upload neste período.",
  "Commands: !uploads stats, !uploads leaderboard and !uploadconfig.": "Comandos: !uploads stats, !uploads leaderboard e !uploadconfig.",
  "Members of <b>{a}</b> ask for something with the command, and the staff claims and finishes it with the buttons of a card.": "Os membros de <b>{a}</b> pedem algo com o comando, e a equipe reivindica e conclui com os botões de um card.",
  "Accept requests": "Aceitar pedidos",
