  "Open requests per member": "Pedidos abertos por membro",
  "Hours to finish a claimed request": "Horas para concluir um pedido reivindicado",
  "0 hours means no limit. After the time, a claimed request goes back to open by itself.": "0 horas significa sem limite. Passado o tempo, um pedido reivindicado volta a aberto sozinho.",
  "Answer to who makes a request": "Resposta a quem faz um pedido",
  "Variables: {request.number}, {request.text}, {request.link}, {request.channel}.": "Variáveis: {request.number}, {request.text}, {request.link}, {request.channel}.",
  "Open requests": "Pedidos abertos",
  "Claimed": "Reivindicado",
  "There are no open requests.": "Não há pedidos abertos.",
  "Commands: !request make, !request list and !requestconfig.": "Comandos: !request make, !request list e !requestconfig.",
  "Members of <b>{a}</b> rate each other from 1 to 5 stars. The profile shows the rating and the numbers of uploads, requests and partnerships.": "Os membros de <b>{a}</b> se avaliam de 1 a 5 estrelas. O perfil mostra a avaliação e os números de uploads, pedidos e parcerias.",
  "Allow reviews": "Permitir avaliações",
  "Channel for new reviews": "Canal das novas avaliações",
  "Every new review is shown there. Empty shows them nowhere.": "Cada nova avaliação é mostrada lá. Vazio não mostra em lugar nenhum.",
  "Commands: !review give, !review show, !review remove, !profile and !profileconfig.": "Comandos: !review give, !review show, !review remove, !profile e !profileconfig.",
  "Uploads": "Uploads",
  "Requests": "Pedidos",
  "Reviews and profiles": "Avaliações e perfis",
  "Free servers can have {a}, Premium {b}.": "Um servidor Free pode ter {a}, Premium {b}.",
  "Up to 5 emojis, separated by spaces. Petto adds them to the message when it sends it. It is the same as writing {reactreply:emoji} for each one.": "Até 5 emojis, separados por espaços. O Petto os adiciona à mensagem quando a envia. É o mesmo que escrever {reactreply:emoji} para cada um.",
  "Cooldown": "Cooldown",
  "0 means no requirement. The cooldown is how long before the same server can partner again, written like 3d 4h, 12h or 30m. Empty is no cooldown.": "0 significa sem requisito. O cooldown é o tempo até o mesmo servidor poder fazer parceria de novo, escrito como 3d 4h, 12h ou 30m. Vazio é sem cooldown.",
  "Refuse servers that Discord marks as NSFW": "Recusar servidores que o Discord marca como NSFW",
  "Blocked words": "Palavras bloqueadas",
  "Servers with one of these words in their name or description are refused. Separated by commas, up to 10.": "Servidores com uma destas palavras no nome ou na descrição são recusados. Separadas por vírgulas, até 10.",
  "Welcome channel": "Canal de boas-vindas",
  "Where a new Partner Manager is welcomed when they are given the role. Empty welcomes only with the command.": "Onde um novo Partner Manager recebe boas-vindas quando ganha o cargo. Vazio só dá boas-vindas com o comando.",
  "NSFW server": "Servidor NSFW",
  "Blocked keyword": "Palavra bloqueada",
  "The cooldown is written like 3d 4h, 12h or 30m, up to a year. The one that was saved stays.": "O cooldown é escrito como 3d 4h, 12h ou 30m, até um ano. O que estava salvo continua.",
  "Each reply can be a text or one of your saved embeds. Empty uses the default. Variables: {partner.name}, {partner.members}, {partner.manager}, {partner.count_week}, {partner.count_total}, {partner.rank_week}, {partner.top_week}, {partner.server_week} and the usual ones like {user.mention}.": "Cada resposta pode ser um texto ou um dos seus embeds salvos. Vazio usa a padrão. Variáveis: {partner.name}, {partner.members}, {partner.manager}, {partner.count_week}, {partner.count_total}, {partner.rank_week}, {partner.top_week}, {partner.server_week} e as de sempre como {user.mention}.",
  "Accept the purchase and refund terms before paying. Turn on JavaScript and press Choose plan again.": "Aceite os termos de compra e reembolso antes de pagar. Ative o JavaScript e clique em Escolher plano de novo.",
  "I'm missing permissions in that channel. I need View Channel, Send Messages and Embed Links.": "Faltam permissões nesse canal. Preciso de Ver canal, Enviar mensagens e Inserir links.",
  "I can't see that channel. Give me View Channel there.": "Não consigo ver esse canal. Me dê Ver canal lá.",
