  "Members cannot get a verification link right now: Petto's VERIFY_BASE_URL is not set.": "Os membros não podem receber um link de verificação agora: a VERIFY_BASE_URL do Petto não está configurada.",
  "Members cannot get a verification link right now: Petto's VERIFY_TOKEN_SECRET is not set.": "Os membros não podem receber um link de verificação agora: o VERIFY_TOKEN_SECRET do Petto não está configurado.",
  "Members cannot get a verification link right now: Petto's VERIFY_BASE_URL is not a web address.": "Os membros não podem receber um link de verificação agora: a VERIFY_BASE_URL do Petto não é um endereço web.",
  "Members cannot get a verification link right now: Petto's VERIFY_BASE_URL points to localhost, which only opens on the bot's computer.": "Os membros não podem receber um link de verificação agora: a VERIFY_BASE_URL do Petto aponta para localhost, que só abre no computador do bot.",
  "Until it is fixed, the panel offers the letters inside Discord instead.": "Até ser corrigido, o painel oferece as letras dentro do Discord.",
  "Color each suggestion by its status": "Colorir cada sugestão conforme o estado",
  "Off by default: the message has no color. Pick the colors below.": "Desativado por padrão: a mensagem não tem cor. Escolha as cores abaixo.",
  "Sums count as a number": "As somas contam como número",
  "2*3+1 is 7. Only whole numbers.": "2*3+1 é 7. Só números inteiros.",
  "A mistake sends the count back to the start": "Um erro volta a contagem para o início",
  "If it is off, the count goes on from where it was.": "Se estiver desligado, a contagem continua de onde estava.",
  "The same person can count twice in a row": "A mesma pessoa pode contar duas vezes seguidas",
  "Off by default: someone else has to count in between.": "Desligado por padrão: outra pessoa precisa contar no meio.",
  "Delete the wrong numbers": "Apagar os números errados",
  "Say when the last number is edited or deleted": "Avisar quando o último número é editado ou apagado",
  "So nobody counts from a number that is not there.": "Assim ninguém conta a partir de um número que não está lá.",
  "Counting": "Contador",
  "A channel where members count one number after the other. A wrong number sends the count back to the start, and the same person cannot count twice in a row.": "Um canal onde os membros contam um número após o outro. Um número errado volta a contagem para o início, e a mesma pessoa não pode contar duas vezes seguidas.",
