  "Delete all {a} backups of this server and turn off the automatic backups? This cannot be undone.": "Apagar todos os {a} backups deste servidor e desligar os backups automáticos? Não dá para desfazer.",
  "Restoring stickers...": "Restaurando figurinhas...",
  "Restoring AutoMod rules...": "Restaurando regras do AutoMod...",
  "Your data": "Seus dados",
  "Automatic backups are off until you turn them on. A backup keeps names, permissions and settings of the server: no messages and no member list. You can delete one backup or all of them at any time. The backups of a server Petto has left are deleted 30 days after the last one.": "Os backups automáticos ficam desligados até você ligá-los. Um backup guarda nomes, permissões e configurações do servidor: sem mensagens e sem lista de membros. Você pode apagar um backup ou todos quando quiser. Os backups de um servidor que o Petto deixou são apagados 30 dias depois do último.",
  "Disable automatic backups": "Desligar os backups automáticos",
  "Nothing is being kept for this server.": "Nada deste servidor está sendo guardado.",
  "Backup deleted.": "Backup apagado.",
  "All backups were deleted and automatic backups are off.": "Todos os backups foram apagados e os automáticos estão desligados.",
  "Only server administrators can delete or restore backups.": "Só administradores do servidor podem apagar ou restaurar backups.",
  "When a member goes offline": "Quando um membro fica offline",
  "Discord hides the Custom Status of a member who is offline or invisible. Choose what Petto does with the role of a rule that reads the Custom Status when that happens.": "O Discord esconde o status personalizado de um membro que está offline ou invisível. Escolha o que o Petto faz nesse caso com o cargo de uma regra que lê o status personalizado.",
  "Role of a member who goes offline": "Cargo de um membro que fica offline",
  "Take the role away (default)": "Tirar o cargo (o padrão)",
  "Keep the role": "Manter o cargo",
  "Sync server data": "Sincronizar dados do servidor",
  "Syncing…": "Sincronizando…",
  "Synced": "Sincronizado",
  "Could not sync. Try again.": "Não foi possível sincronizar. Tente de novo.",
  "Reload the roles, channels and server data from Discord": "Recarrega os cargos, canais e dados do servidor do Discord",
  "Petto only takes away roles it gave itself, and gives the role back, and thanks the member again, when they are online with a matching status. A member it simply has no presence for is never changed. If another rule for the same role (a name or a Server Tag rule) still matches, the role stays.": "O Petto só tira os cargos que ele mesmo deu, e devolve o cargo e agradece de novo ao membro, quando está online com um status que coincide. Um membro de quem ele simplesmente não tem presença nunca é alterado. Se outra regra do mesmo cargo (de nome ou de Server Tag) ainda coincidir, o cargo fica.",
  "Petto only takes away roles it gave itself, and gives the role back, without thanking the member again, when they are online with a matching status. A member it simply has no presence for is never changed. If another rule for the same role (a name or a Server Tag rule) still matches, the role stays.": "O Petto só tira os cargos que ele mesmo deu, e devolve o cargo, sem agradecer de novo ao membro, quando está online com um status que coincide. Um membro de quem ele simplesmente não tem presença nunca é alterado. Se outra regra do mesmo cargo (de nome ou de Server Tag) ainda coincidir, o cargo fica.",
  "Pick channels": "Escolha canais",
  "Pick roles": "Escolha cargos",
  "Nobody found": "Ninguém encontrado",
