  "The points given from now on are listed here.": "Os pontos dados a partir de agora aparecem aqui.",
  "Boosters of <b>{a}</b> make their own colored role with <code>{p}boosterrole create</code> and change it themselves. Here you choose what they may change, and you can manage every booster role.": "Os boosters de <b>{a}</b> criam o próprio cargo colorido com <code>{p}boosterrole create</code> e o mudam sozinhos. Aqui você escolhe o que eles podem mudar e pode gerenciar cada cargo de booster.",
  "Server boost level": "Nível de boost do servidor",
  "No longer boosting": "Não dão mais boost",
  "Petto did not answer, so the list shows the saved roles without their Discord details. Changes may not work right now.": "O Petto não respondeu, então a lista mostra os cargos salvos sem os dados do Discord. As mudanças podem não funcionar agora.",
  "Petto needs the Manage Roles permission to create and change booster roles.": "O Petto precisa da permissão Gerenciar cargos para criar e mudar cargos de booster.",
  "When off, boosters cannot create or change a role. They can still remove theirs, and staff can still manage them here.": "Desligado, os boosters não podem criar nem mudar um cargo. Ainda podem remover o deles, e a staff ainda pode gerenciá-los aqui.",
  "Place new roles above": "Colocar os cargos novos acima de",
  "The Server Booster role (default)": "O cargo Server Booster (padrão)",
  "New booster roles go right above this role, newest on top, so their color shows. Petto's own role must be higher.": "Os cargos de booster novos ficam logo acima deste cargo, o mais novo no topo, para a cor aparecer. O cargo do Petto precisa estar mais acima.",
  "What boosters can change": "O que os boosters podem mudar",
  "Gradients (a second color)": "Degradês (uma segunda cor)",
  "Role icons": "Ícones de cargo",
  "(needs boost level 2)": "(precisa de nível de boost 2)",
  "Color wait (h)": "Espera de cor (h)",
  "Rename wait (h)": "Espera de nome (h)",
  "Icon wait (h)": "Espera de ícone (h)",
  "Hours a booster waits between two changes of the same kind. 0 = no wait.": "Horas que um booster espera entre duas mudanças do mesmo tipo. 0 = sem espera.",
  "Share with up to": "Compartilhar com até",
  "0 = no limit. Boosters share their role with friends with <code>{p}boosterrole share @member</code>.": "0 = sem limite. Os boosters compartilham o cargo com amigos com <code>{p}boosterrole share @membro</code>.",
  "Name filter": "Filtro de nomes",
  "One word or phrase per line": "Uma palavra ou frase por linha",
