  "Add a role to ping": "Adicionar um cargo para mencionar",
  "Add one and Petto will post its news here as soon as they happen.": "Adicione uma e o Petto publicará aqui as novidades assim que acontecerem.",
  "All feeds": "Todos os feeds",
  "Always show it": "Mostrar sempre",
  "Automatic shows the cover of videos and streams, and leaves it out for Shorts.": "Automático mostra a capa de vídeos e transmissões, e a omite nos Shorts.",
