  "Paste the link of the channel or its @name.": "Cole o link do canal ou o @nome.",
  "Paste the link of the channel or its name.": "Cole o link do canal ou o nome.",
  "Paste the link of the profile or its handle.": "Cole o link do perfil ou o usuário.",
  "Search a project or paste the link of the mod, plugin or pack to follow its versions. Or type \"new\" (or \"new mods\", \"new shaders\"…) for the newest projects of Modrinth. That list can be busy.": "Busque um projeto ou cole o link do mod, plugin ou pack para seguir as versões. Ou digite «new» (ou «new mods», «new shaders»…) para os projetos mais novos do Modrinth. Essa lista pode ser bem movimentada.",
  "Kick channel": "Canal da Kick",
  "Subreddit": "Subreddit",
  "Paste the link of the subreddit or write r/name.": "Cole o link do subreddit ou escreva r/nome.",
  "Steam game or list": "Jogo ou lista da Steam",
  "Search a game or paste the link of its Steam store page to follow its news. Or type \"new\" for the new releases of the store, \"top\" for the top sellers, or \"coming soon\". Those lists can be busy.": "Busque um jogo ou cole o link da página dele na loja da Steam para seguir as novidades. Ou digite «new» para os lançamentos novos da loja, «top» para os mais vendidos, ou «coming soon». Essas listas podem ser bem movimentadas.",
  "GitHub repository": "Repositório do GitHub",
  "Paste the link of the repository or write owner/name. Its new releases are posted.": "Cole o link do repositório ou escreva dono/nome. As novas versões (releases) são publicadas.",
