  "Paste the link of a profile or of one of its boards.": "Cole o link de um perfil ou de um dos quadros.",
  "Website or feed": "Site ou feed",
  "Paste the link of a blog, a news site or its RSS feed. Petto finds the feed.": "Cole o link de um blog, de um site de notícias ou do feed RSS. O Petto encontra o feed.",
  "New episodes": "Novos episódios",
  "Of the day": "Do dia",
  "Locked for now": "Bloqueado por enquanto",
  "Premium, locked for now": "Premium, bloqueado por enquanto",
  "These services cost money to follow, so they will be Premium only to cover that cost. They unlock when they are ready.": "Seguir esses serviços custa dinheiro, então serão só Premium para cobrir esse custo. Desbloqueiam quando estiverem prontos.",
  "Locked": "Bloqueado",
  "X charges for its API, so following accounts there has a monthly cost.": "O X cobra pela API, então seguir contas lá tem um custo mensal.",
  "Instagram has no public way to follow an account; a paid provider is needed.": "O Instagram não tem uma forma pública de seguir uma conta; é preciso um provedor pago.",
  "TikTok has no public way to follow an account; a paid provider is needed.": "O TikTok não tem uma forma pública de seguir uma conta; é preciso um provedor pago.",
  "Free servers follow up to {count} accounts of each platform, Premium servers up to {premium}.": "Servidores grátis seguem até {count} contas de cada plataforma, os Premium até {premium}.",
  "{used} of {limit} {name} accounts": "{used} de {limit} contas de {name}",
  "{used} followed, up to {limit} of each platform": "{used} seguidas, até {limit} de cada plataforma",
  "You follow the {count} {name} accounts a free server can. Premium servers can follow up to {premium} of each platform.": "Você segue as {count} contas de {name} que um servidor grátis permite. Servidores Premium podem seguir até {premium} de cada plataforma.",
  "{count} of {limit} followed": "{count} de {limit} seguidas",
  "Write one to four words first.": "Escreva primeiro de uma a quatro palavras.",
  "pink flower anime -character": "pink flower anime -character",
  "Which animals": "Quais animais",
  "Pick the ones you want, or none to get any of them.": "Escolha os que quiser, ou nenhum para receber qualquer um deles.",
  "Tags": "Tags",
  "One to four words in English, like pink, cats aesthetic or anime roses. Add anime to get anime pictures, memes for funny ones (cat memes) and a minus sign to leave a word out (pink flower anime -character).": "De uma a quatro palavras em inglês, como pink, cats aesthetic ou anime roses. Adicione anime para imagens de anime, memes para as engraçadas (cat memes) e um sinal de menos para tirar uma palavra (pink flower anime -character).",
  "Animals": "Animais",
  "Cats": "Gatos",
  "Dogs": "Cachorros",
  "Foxes": "Raposas",
  "Birds": "Aves",
  "Ducks": "Patos",
  "Capybaras": "Capivaras",
  "Bunnies": "Coelhos",
  "Random music": "Música aleatória",
  "New projects": "Projetos novos",
  "A picture of an animal every so often. Pick which ones, or leave them all.": "Uma imagem de um animal de tempos em tempos. Escolha quais, ou deixe todos.",
  "A song picked at random from Deezer, Apple Music and Spotify, every so often.": "Uma música aleatória do Deezer, Apple Music e Spotify, de tempos em tempos.",
  "A picture of what you write (a color, a thing, a mood, anime roses), every so often. Pinterest has no public search, so Petto searches several places for safe pictures: Wallhaven and Safebooru for anime, Google, Pixabay, Pexels and Unsplash when the bot has their keys, Openverse and Flickr.": "Uma imagem do que você escrever (uma cor, uma coisa, um clima, anime rosas), de tempos em tempos. O Pinterest não tem busca pública, então o Petto procura imagens seguras em vários lugares: Wallhaven e Safebooru para anime, Google, Pixabay, Pexels e Unsplash se o bot tiver as chaves, Openverse e Flickr.",
  "Tells you when Epic Games gives a game for free, and when the next one comes.": "Avisa quando a Epic Games dá um jogo de graça, e quando chega o próximo.",
  "The featured article of Wikipedia, every so often.": "O artigo em destaque da Wikipédia, de tempos em tempos.",
  "The daily chess puzzle of Chess.com, every so often.": "O problema de xadrez do dia do Chess.com, de tempos em tempos.",
  "A Pokémon from the Pokédex, every so often.": "Um Pokémon da Pokédex, de tempos em tempos.",
  "Show the video player": "Mostrar o player do vídeo",
  "Posts the link instead of the card, so Discord plays the video right there. Streams keep their card.": "Publica o link em vez do cartão, assim o Discord reproduz o vídeo ali mesmo. As lives mantêm o cartão.",
  "Button type": "Tipo de botão",
  "Choose a saved embed": "Escolha um embed salvo",
  "Where it is shown": "Onde é mostrado",
  "Only to who clicked": "Só para quem clicou",
