  "Petto needs View Channel and Send Messages here": "O Petto precisa de «Ver canal» e «Enviar mensagens» aqui",
  "The ping will not arrive in these channels:": "O ping não vai chegar nestes canais:",
  "Give Petto View Channel and Send Messages in them, or pick other channels.": "Dê ao Petto «Ver canal» e «Enviar mensagens» neles, ou escolha outros canais.",
  "Give Petto the permission there, or pick another channel, or nothing will arrive.": "Dê ao Petto a permissão lá, ou escolha outro canal; senão, nada vai chegar.",
  "Give Petto the permission there, or edit the feed and pick another channel.": "Dê ao Petto a permissão lá, ou edite o feed e escolha outro canal.",
  "Support mode": "Modo suporte",
  "You are looking at a server you do not manage. You can change the settings that fix errors (channels, messages and delays). Everything else is read-only, and every change you make is recorded for the admins of the server.": "Você está vendo um servidor que não gerencia. Pode alterar as configurações que corrigem erros (canais, mensagens e atrasos). Todo o resto é somente leitura, e cada alteração que você faz fica registrada para os admins do servidor.",
  "You can save the editable parts of this page.": "Você pode salvar as partes editáveis desta página.",
  "This page is read-only in Support mode.": "Esta página é somente leitura no modo suporte.",
  "Editable in Support mode: {list}.": "Editável no modo suporte: {list}.",
  "Support mode: this setting is not editable on other servers": "Modo suporte: esta configuração não pode ser editada em outros servidores",
  "Support change on this server": "Alteração de suporte neste servidor",
  "The owner of Petto changed a setting of this server from the dashboard (Support mode).": "O dono do Petto alterou uma configuração deste servidor pelo dashboard (modo suporte).",
  "Who": "Quem",
