  "The author can change the title": "O autor pode mudar o título",
  "One check every minute that only looks at the posts that are due.": "Uma verificação por minuto que só olha as postagens que chegaram a hora.",
  "Quiet posts: after how many days (0 is off)": "Postagens sem atividade: depois de quantos dias (0 é desligado)",
